python3 -c 'exec("import os,time\nfrom math import isqrt\ndef encode(k):\n K=k+1;B=4*K\n c=sum(((2*a+1-q%2)*K+(q^1))*B**(2*q+a) for q in range(k) for a in (0,1))\n v=c+k-1\n return v*(v+1)//2+c\ndef table(p):\n v=(isqrt(8*p+1)-1)//2;c=p-v*(v+1)//2;k=v-c+1;K=k+1;B=4*K\n out=[]\n for q in range(k):\n  for a in (0,1):\n   u=c//B**(2*q+a)%B;z,r=divmod(u,K);out.append((q,a,r,z//2,2*(z%2)-1))\n return out\nk=0;old=[]\ntry:\n cap=int(os.getenv(\"CL_MAX_STATES\",\"64\"));delay=float(os.getenv(\"CL_INTERVAL\",\"1\"))\n assert 2<=cap<=128 and cap%2==0 and .05<=delay<=3600\n while True:\n  if k<cap:\n   n=k+2;rows=table(encode(n))\n   assert len(rows)==2*n and rows[:len(old)]==old\n   for q,a,r,b,d in rows:\n    assert (r,b,d)==(q^1,a,1-2*(q%2))\n    assert rows[2*r+b][2:]==(q,a,-d)\n   old=rows;k=n\n   print(\"COSMIC_LOVE\",flush=True)\n  time.sleep(delay)\nexcept (ValueError,AssertionError,OverflowError,MemoryError):\n raise SystemExit(2)\n")'
